  private static var cache: [String: NSImage] = [:]
  static func image(_ name: String, size: CGFloat, color: NSColor) -> NSImage? {
    guard let source = artwork[name], let rgb = color.usingColorSpace(.sRGB) else { return nil }
    let hex = String(format: "#%02x%02x%02x", Int((rgb.redComponent * 255).rounded()), Int((rgb.greenComponent * 255).rounded()), Int((rgb.blueComponent * 255).rounded()))
    let key = "\(name)|\(size)|\(hex)"
    if let existing = cache[key] { return existing }
    guard let image = NSImage(data: Data(source.replacingOccurrences(of: "currentColor", with: hex).utf8)) else { return nil }
    image.size = NSSize(width: size, height: size)
    if cache.count > 512 { cache.removeAll() }
    cache[key] = image
    return image
  }
